function Modal({ title, children, close }: { title: string; children: ReactNode; close: () => void }) {
  const panel = useRef<HTMLElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden'; panel.current?.querySelector<HTMLElement>('button')?.focus();
    const trap = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;
      const elements = [...(panel.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled])') || [])];
      const first = elements[0], last = elements.at(-1);
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    };
    document.addEventListener('keydown', trap);
    return () => { document.removeEventListener('keydown', trap); document.body.style.overflow = previousOverflow; previous?.focus(); };
  }, []);
  useEffect(() => { const fn = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); }; window.addEventListener('keydown', fn); return () => window.removeEventListener('keydown', fn); }, [close]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) close(); }}><section ref={panel} role="dialog" aria-modal="true" aria-label={title} className="modal"><header><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="关闭"><Icon icon={X}/></button></header>{children}</section></div>;
}
